      "tail": "ཁྱད་པར་ཅན་ཐམས་ཅད་དམན་པའི་ལྟ་བུའོ་"
    },
    {
      "label": "QUOTE",
      "frame": "རང་འགྲེལ་ལས།",
      "head": "རྒྱུད་གཅིག་ལ་ངེས་པའི་ཟག་པ་མེད་པའི་ཆོས་མངོན་ཐོབ་པ། ཕྱིས་མ་སྐྱེས་པའི་",
      "tail": "སྐལ་བ་མཉམ་པའི་རྒྱུ་མ་འོངས་པ་ནི་མེད་དོ་"
    },
    {
      "label": "QUOTE",
      "frame": "རྒྱལ་སྲས་ལས།",
      "head": "འདི་ལ་སྡུག་བསྔལ་ལ་ཆོས་ཤེས་པའི་བཟོད་པ་མ་འོངས་པ་དག་ལས། སྡུག་བསྔལ་",
      "tail": "དེ་དག་ནི་མ་སྐྱེས་པའི་ཕྱིར་རོ་"
    },
    {
