      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རང་འགྲེལ་ལས།",
      "head": "གང་དག་རྟེན་མཚུངས་པ་ཡོད་པའི་སེམས་དང་སེམས་ལས་བྱུང་བ་དེ་དག་ནི་ཕན་",
      "tail": "མཚུངས་པར་ལྡན་པའི་རྒྱུ་ཡིན་ནོ་"
    },
    {
      "label": "QUOTE",
      "frame": "རང་འགྲེལ་ལས།",
      "head": "གང་དག་རྟེན་མཚུངས་པ་ཡོད་པའི་སེམས་དང་སེམས་ལས་བྱུང་བ་དེ་དག་ཕན་ཚུན་",
      "tail": "སྦྱོར་བ་ཡིན་ནོ་"
    },
    {
      "label": "QUOTE",
      "frame": "རང་འགྲེལ་ལས།",
      "head": "འདི་ནི་ཉོན་མོངས་པ་ཅན་གྱི་ཆོས་ཀྱི་ཐུན་མོང་གི་རྒྱུ་ཉིད་ཡིན་པས་ན་སྐལ་པ་མཉམ་",
      "tail": "སྐྱེ་བར་འགྱུར་རོ་"
    },
    {
