      "frame": "ཞེས་འཆད་པ།",
      "head": "སྡུག་བསྔལ་རྒྱུ་མཚོང་སྤང་བྱ་བ། །ལྟ་དང་དེ་བཞིན་ཐེ་ཚོམ་དང་། །གང་དེའང་ལྷན་",
      "tail": "ཀུན་ཏུ་འགྲོ། །"
    },
    {
      "label": "QUOTE",
      "frame": "རང་འགྲེལ་ལས།",
      "head": "རྣམ་པར་སྨིན་པའི་རྒྱུ་ཞིག་རྣམ་པར་སྨིན་པ་ཡིན་ནམ། འོན་ཏེ་རྣམ་པར་སྨིན་པ་ཉིད་",
      "tail": "སྔར་བཤད་ཟིན་ཏོ་"
    },
    {
      "label": "QUOTE",
      "frame": "རང་འགྲེལ་ལས།",
      "head": "དེ་ལ་རྣམ་པར་སྨིན་པའི་རྒྱུ་ལས་སྐྱེས་པ་ནི། རྣམ་པར་སྨིན་ལས་སྐྱེས་པ་སྟེ། བར་",
      "tail": "རྒྱུ་ལ་འབྲས་བུ་བཏགས་པ་ཡིན་ཏེ་"
    },
    {
      "label": "QUOTE",
      "frame": "རང་འགྲེལ་ལས།",
      "head": "ཡང་རྣམ་པར་སྨིན་པ་ཞེས་བྱ་བའི་དོན་ཅི་ཞེ་ན། མི་འདྲ་བར་སྨིན་པ་ནི་རྣམ་པར་",
      "tail": "སྨིན་པའོ་"
    },
    {
      "label": "QUOTE",
      "frame": "རང་འགྲེལ་ལས།",
      "head": "འབྲས་བུའི་ཆོས་རྣམས་གང་ཞེ་ན། འདུས་བྱས་ཀྱི་ཆོས་ཐམས་ཅད་དང་། །སོ་སོར་",
      "tail": "བརྟགས་པའི་འགོག་པ་འོ། །"
    },
    {
      "label": "QUOTE",
      "frame": "རང་འགྲེལ་ལས།",
      "head": "ཅིའི་ཕྱིར་ཞེ་ན། རྒྱུ་རྣམ་པ་དྲུག་མི་སྲིད་པའི་ཕྱིར་དང་། འབྲས་བུ་རྣམ་པ་ལྔ་མི་",
      "tail": "སྲིད་པའི་ཕྱིར་རོ་ཅེས་སོ། །"
    }
  ]
